<?php
 namespace ehr; interface iPractitionerResource extends iResource { } class PractitionerResource extends Resource implements iPractitionerResource { protected $doctorGUID; public function getDoctorGUID(): string { return $this->doctorGUID; } public function setDoctorGUID(string $guid): void { $this->doctorGUID = $guid; } public function getLink(): ?PractitionerLink { return $this->basicLink; } public function setLink(PractitionerLink $link): void { $this->basicLink = $link; } public function getItem(): ?PractitionerResourceItem { return $this->basicItem; } public function setItem(PractitionerResourceItem $item): void { $this->basicItem = $item; } public function __construct(PractitionerLink $link, string $aName, string $aTableName, $aSource) { parent::__construct($link, $aName, $aTableName, $aSource); $this->doctorGUID = null; } public function createResourceItem(): void { $this->basicItem = new PractitionerResourceItem($this); } public function getItemFromDB(int $key): string { if (empty($this->getDoctorGUID())) { return selectSql($this->getLink()->getConnetDb(), "select codehl7 from MedDoctor where medDoctorCpde = {$key}"); } return $this->getDoctorGUID(); } private function addNewDoctor(PractitionerResourceItem $item): void { $link = $this->getLink(); $exchange = $link->getExchange(); $this->json = $exchange->getJSONResult( $exchange->rfc( "{$link->getLs()->getParam('urlDPC')}Practitioner", Exchange::HTTP_POST, $item->getJSONData() ), "при регистрации в ЦОД врача, {$this->makeMessageDoctorInfo($item, false)}", true ); $item->setGUID(LinkJSON::getNodeValueByPath($this->json, 'id')); if (empty($item->getGUID())) { $link->getLogger()->addLog( "ошибка получения GUID регистрации в ЦОД врача, {$this->makeMessageDoctorInfo($item, false)}", '', logger::LMT_ERROR, true); } $this->dbUpdateDoctorGUID($item); } private function dbUpdateDoctorGUID(PractitionerResourceItem $item): void { executeSql($this->getLink()->getConnetDb(), <<<"EOT"
update MedDoctor set
       codeHL7 = '{$item->getGUID()}',
       state = null
where medDoctorCode = {$item->getId()}
EOT
); $item->setState(0); } private function makeMessageDoctorInfo(PractitionerResourceItem $item, bool $guid = true, bool $key = true): string { return "ФИО {$item->getFIO()}" . ($key ? ", key: {$item->getId()}" : '') . ($guid ? ($item->getGUID() ? ", GUID: {$item->getGUID()}" : '') : ''); } public function sendItem2DPC(int $key): ?string { parent::sendItem2DPC($key); $item = $this->getItem(); if ($item->getState() === 1 || empty($item->getGUID())) { if (empty($item->getGUID())) { $this->addNewDoctor($item); } else { $link = $this->getLink(); $exchange = $link->getExchange(); $logger = $link->getLogger(); $this->json = $exchange->getJSONResult( $exchange->rfc("{$link->getLs()->getParam('urlDPC')}Practitioner/{$item->getGUID()}?_format=json"), "при поиске в ЦОД врача, {$this->makeMessageDoctorInfo($item)}", false ); if ($link->getAnswerCode() === 404) { $logger->addLog( "! попытка повторной регистрации в ЦОД врача, {$this->makeMessageDoctorInfo($item)}" ); $item->clearGUIDs(); $item->initJSONbase(); $this->addNewDoctor($item); $logger->addLog( "! повторно зарегистрирован в ЦОД врач, {$this->makeMessageDoctorInfo($item)}" ); } else { if (!$exchange->validResult($link->getAnswerCode())) { return null; } $item->setVersionGUID(LinkJSON::getNodeValueByPath($this->json, LinkJSON::SOURCE_VERSION_ID)); if (empty($item->getVersionGUID())) { $logger->addLog( "ошибка получения в ЦОД GUID версии врача, {$this->makeMessageDoctorInfo($item)}", '', logger::LMT_ERROR, true ); } else { $item->appendJSON(); $this->json = $exchange->getJSONResult( $exchange->rfc( "{$link->getLs()->getParam('urlDPC')}Practitioner/{$item->getGUID()}", Exchange::HTTP_PUT, $item->getJSONData() ), "при обновлении в ЦОД врача, {$this->makeMessageDoctorInfo($item)}", true ); $this->dbUpdateDoctorGUID($item); } } } } return $item->getGUID(); } public function afterOpenBeforeSend(): void { } } 